  for(const [a,c]of[[-half,-inner],[-inner,0],[0,inner],[inner,half]])box(b,'nong-entry-transom',(a+c)/2,(E.curtainH+E.h)/2,0,c-a-.09,E.h-E.curtainH-.10,.025,glass,28);
