function geometry(){const g=new Y.Geo.Geometry(),size=1.46,slope=.06/1.87;
 const midpoint=(a,b)=>a.map((x,i)=>(x+b[i])/2);
 function curve(a,b,c,d,out,depth=0){const dx=d[0]-a[0],dy=d[1]-a[1],len=Math.hypot(dx,dy),dist=p=>len?Math.abs(dx*(a[1]-p[1])-(a[0]-p[0])*dy)/len:Math.hypot(p[0]-a[0],p[1]-a[1]);
  if(depth>=12||Math.max(dist(b),dist(c))<=.015){out.push(d);return;}
  const ab=midpoint(a,b),bc=midpoint(b,c),cd=midpoint(c,d),abc=midpoint(ab,bc),bcd=midpoint(bc,cd),mid=midpoint(abc,bcd);curve(a,ab,abc,mid,out,depth+1);curve(mid,bcd,cd,d,out,depth+1);
 }
 for(const path of PATHS){const rings=[];let ring=[];
  const close=()=>{if(ring.length>2){if(ring[0][0]!==ring.at(-1)[0]||ring[0][1]!==ring.at(-1)[1])ring.push(ring[0]);rings.push(ring);}ring=[];};
  for(const [op,...v]of path){if(op==='mo'){close();ring=[[v[0],v[1]]];}else if(op==='li')ring.push(v);else if(op==='cv')curve(ring.at(-1),v.slice(0,2),v.slice(2,4),v.slice(4,6),ring);else close();}close();
  for(const t of Y.Footprints.capTriangles(rings)){const ps=t.map(([x,y])=>{const yy=1.105+(.5-y/259.0103)*size;return[-1.48+(x/259.0103-.5)*size,yy,.34-(yy-.17)*slope+.004];});const fp=ps.map(p=>p.map(Math.fround)),n=Y.M.cross(Y.M.sub(fp[1],fp[0]),Y.M.sub(fp[2],fp[0]));if(Math.hypot(...n)>1e-16)g.tri(...fp,t.map(p=>p.map(v=>v/259.0103)));}
 }return g;
}
