function outsideRect(g,rect){const out=new G.Geometry();let changed=false;
 for(let i=0;i<g.v.length;i+=24){const raw=[0,8,16].map(j=>Array.from(g.v.slice(i+j,i+j+8)));
  if(raw.every(v=>v[0]<=rect[0])||raw.every(v=>v[0]>=rect[1])||raw.every(v=>v[1]<=rect[2])||raw.every(v=>v[1]>=rect[3])){out.v.push(...g.v.slice(i,i+24));continue;}
  let inside=raw;const parts=[];
  for(const fn of[v=>v[0]-rect[0],v=>rect[1]-v[0],v=>v[1]-rect[2],v=>rect[3]-v[1]]){if(!inside.length)break;const exterior=clip(inside,fn);if(exterior.length>=3&&inside.some(v=>fn(v)<0))parts.push(exterior);inside=clip(inside,v=>-fn(v));}
  if(inside.length>=3)changed=true;
  for(const poly of parts)for(let j=1;j<poly.length-1;j++){const t=[poly[0],poly[j],poly[j+1]].map(v=>v.map((n,k)=>k<3?Math.fround(n):n)),n=M.cross(M.sub(t[1],t[0]),M.sub(t[2],t[0]));if(M.dot(n,n)>1e-16&&M.dot(n,t[0].slice(3,6))>0)for(const v of t)out.v.push(...v);}
 }return changed?out:g;
}

