const pointers=new Map();function pointerDown(e){if(e.button>2)return;routePlaying=false;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});e.currentTarget.setPointerCapture(e.pointerId);gesture={x:e.clientX,y:e.clientY,startX:e.clientX,startY:e.clientY,moved:false,button:e.button,shift:e.shiftKey};if(pointers.size===2){const a=[...pointers.values()];gesture.pinch=Math.hypot(a[0].x-a[1].x,a[0].y-a[1].y)}root.classList.add('dragging')}
function pointerMove(e){if(!pointers.has(e.pointerId)||!gesture)return;const dx=e.clientX-gesture.x,dy=e.clientY-gesture.y;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===2){const a=[...pointers.values()],d=Math.hypot(a[0].x-a[1].x,a[0].y-a[1].y);if(gesture.pinch)zoom(gesture.pinch/d);gesture.pinch=d;gesture.moved=true;}else if(mode!=='3d'){const m=planView.w/innerWidth;planView.x-=dx*m;planView.z-=dy*m;drawPlan();}else if(gesture.button===2||gesture.shift){const m=orbit.distance*.0008,c=Math.cos(orbit.yaw),s=Math.sin(orbit.yaw);orbit.target[0]-=(dx*c+dy*s)*m;orbit.target[2]-=(-dx*s+dy*c)*m;}else{orbit.yaw-=dx*.006;orbit.elevation=M.clamp(orbit.elevation+dy*.005,.18,1.56)}gesture.moved ||= Math.hypot(e.clientX-gesture.startX,e.clientY-gesture.startY)>5;gesture.x=e.clientX;gesture.y=e.clientY;}
function pointerUp(e){const click=gesture&&!gesture.moved&&pointers.size===1;pointers.delete(e.pointerId);if(click&&ready){if(mode==='3d'){const id=engine.pick(e.clientX,e.clientY);if(by.has(id))select(id,false);}else{const v=planBox(),q=[v[0]+e.clientX/innerWidth*v[2],v[1]+e.clientY/innerHeight*v[3]];const hit=[...selectable].reverse().find(f=>f.geometry.type==='Point'?Math.hypot(q[0]-point(f)[0],q[1]-point(f)[1])<5:F.inside(q,f.geometry));if(hit)select(hit.properties.pickId,false);}}if(!pointers.size){gesture=null;root.classList.remove('dragging')}else{const a=[...pointers.values()][0];gesture={x:a.x,y:a.y,startX:a.x,startY:a.y,moved:true,button:0};}}
for(const e of [canvas,svg]){e.addEventListener('pointerdown',pointerDown);e.addEventListener('pointermove',pointerMove);e.addEventListener('pointerup',pointerUp);e.addEventListener('pointercancel',()=>{gesture=null;pointers.clear();root.classList.remove('dragging')});e.addEventListener('contextmenu',e=>e.preventDefault());e.addEventListener('wheel',e=>{e.preventDefault();zoom(Math.exp(e.deltaY*.001))},{passive:false})}
function routeOptions(){for(const sel of ['route-from','route-to']){const list=sel==='route-from'?selectable.filter(f=>f.properties.kind==='gate'):selectable.filter(f=>['building','pier','heritage'].includes(f.properties.kind));for(const f of list){const o=document.createElement('option');o.value=f.properties.pickId;o.textContent=f.properties.label;$(sel).append(o)}}}
function planRoute(){if(!campus)return;const from=by.get(+$('route-from').value),to=by.get(+$('route-to').value);if(!from||!to)return;const g=campus.network,a=Y.Network.nearest(g,point(from)),b=Y.Network.nearest(g,point(to));route=a&&b?Y.Network.route(g,a.p,b.p):null;routePlaying=false;routeDistance=0;if(!route){state.routeEdges=new Set();$('route-status').textContent='这两个附近路段在现有公开路网中未连通，暂不补画连接。';$('route-progress').disabled=$('route-play').disabled=true;drawPlan();return}if(route.length===0){route=null;state.routeEdges=new Set();$('route-status').textContent='这两个位置之间没有需要浏览的路段。';$('route-progress').value=0;$('route-progress').disabled=$('route-play').disabled=true;drawPlan();return}state.routeEdges=new Set(Y.Network.routeEdges(g,route));const gap=Math.round(Math.hypot(point(to)[0]-b.p[0],point(to)[1]-b.p[1]));$('route-status').textContent=`公开路网约 ${Math.round(route.length)} 米；终点是距对象中心约 ${gap} 米的道路节点。`;$('route-progress').disabled=$('route-play').disabled=false;$('route-play').textContent='沿路浏览';$('route-progress').value=0;drawPlan();say('路线只沿现有地图道路显示。');}
function moveAlong(){if(!route)return;const p=Y.Network.sample(route.points,routeDistance);if(mode==='3d'){orbit.target=[p.point[0],1+(Y.Landscape42?.elevation(...p.point)||0),p.point[1]];orbit.distance=125;orbit.elevation=.73;}else{planView.x=p.point[0];planView.z=p.point[1];planView.w=Math.min(planView.w,310);drawPlan();}$('route-progress').value=String(Math.round(routeDistance/route.length*1000));}
function clearRoute(){route=null;routePlaying=false;state.routeEdges=new Set();$('route-status').textContent='选择校门和对象，查看公开道路网络。';$('route-progress').disabled=$('route-play').disabled=true;drawPlan();}
